  put("Why flow nitrogen while brazing refrigerant lines?", {q: T("Why flow nitrogen while brazing refrigerant lines?", "¿Por qué hacer pasar nitrógeno al soldar líneas de refrigerante?"), a: [T("To prevent oxide scale inside the tube", "Para evitar escoria de óxido dentro del tubo"), T("To cool the joint faster", "Para enfriar más rápido la unión"), T("To find leaks while brazing", "Para encontrar fugas al soldar"), T("Code requires a flame boost", "El código exige avivar la flama")], c: 0, why: T("Without oxygen inside, copper doesn't scale; scale can plug filters and metering devices.", "Sin oxígeno dentro el cobre no forma escoria, que puede tapar filtros y dispositivos de expansión."), wrong: ["", T("Not To cool the joint faster. The right call is To prevent oxide scale inside the tube.", "No es Para enfriar más rápido la unión. La correcta es Para evitar escoria de óxido dentro del tubo."), T("Not To find leaks while brazing. The right call is To prevent oxide scale inside the tube.", "No es Para encontrar fugas al soldar. La correcta es Para evitar escoria de óxido dentro del tubo."), T("Not Code requires a flame boost. The right call is To prevent oxide scale inside the tube.", "No es El código exige avivar la flama. La correcta es Para evitar escoria de óxido dentro del tubo.")], tip: T("Without oxygen inside, copper doesn't scale; scale can plug filters and metering devices.", "Sin oxígeno dentro el cobre no forma escoria, que puede tapar filtros y dispositivos de expansión.")});
  put("After isolating the pump, the micron gauge rises fast and never levels off. This indicates:", {q: T("After isolating the pump, the micron gauge rises fast and never levels off. This indicates?", "Al aislar la bomba, el vacuómetro sube rápido y no se estabiliza. Indica:?"), a: [T("A leak", "Una fuga"), T("Normal moisture boil-off", "Humedad normal evaporándose"), T("A good vacuum", "Un buen vacío"), T("Too much oil", "Demasiado aceite")], c: 0, why: T("A steady climb toward atmosphere means air is getting in. Moisture causes a rise that levels off.", "Una subida constante hacia la atmósfera significa que entra aire. La humedad causa una subida que se estabiliza."), wrong: ["", T("Not Normal moisture boil-off. The right call is A leak.", "No es Humedad normal evaporándose. La correcta es Una fuga."), T("Not A good vacuum. The right call is A leak.", "No es Un buen vacío. La correcta es Una fuga."), T("Not Too much oil. The right call is A leak.", "No es Demasiado aceite. La correcta es Una fuga.")], tip: T("A steady climb toward atmosphere means air is getting in. Moisture causes a rise that levels off.", "Una subida constante hacia la atmósfera significa que entra aire. La humedad causa una subida que se estabiliza.")});
  put("On a TXV system, after verifying airflow, the charge is fine-tuned by:", {q: T("On a TXV system, after verifying airflow, the charge is fine-tuned by:", "En un sistema con TXV, tras verificar el flujo, la carga se afina por:"), a: [T("Subcooling", "Subenfriamiento"), T("Superheat only", "Solo sobrecalentamiento"), T("Suction pressure alone", "Solo presión de succión"), T("Amp draw", "Amperaje")], c: 0, why: T("A TXV controls superheat itself, so subcooling shows the charge.", "La TXV controla el sobrecalentamiento, así que el subenfriamiento indica la carga."), wrong: ["", T("Not Superheat only. The right call is Subcooling.", "No es Solo sobrecalentamiento. La correcta es Subenfriamiento."), T("Not Suction pressure alone. The right call is Subcooling.", "No es Solo presión de succión. La correcta es Subenfriamiento."), T("Not Amp draw. The right call is Subcooling.", "No es Amperaje. La correcta es Subenfriamiento.")], tip: T("A TXV controls superheat itself, so subcooling shows the charge.", "La TXV controla el sobrecalentamiento, así que el subenfriamiento indica la carga.")});
