  put("A customer wants an R-410A condenser 'converted' to R-454B. You explain:", {q: T("A customer wants an R-410A condenser 'converted' to R-454B. You explain:", "Un cliente quiere 'convertir' una condensadora R-410A a R-454B. Le explicas:"), a: [T("Not allowed or safe; A2L equipment is designed and listed for it", "No está permitido ni es seguro; el equipo A2L se diseña y certifica para eso"), T("Just swap the refrigerant", "Solo se cambia el refrigerante"), T("Change the oil and it's fine", "Se cambia el aceite y listo"), T("It works if you add a filter-drier", "Funciona con un filtro deshidratador")], c: 0, why: T("There are no drop-ins. A2L equipment has listed safety features and charge limits.", "No hay reemplazos directos. El equipo A2L tiene seguridades certificadas y límites de carga."), wrong: ["", T("Not Just swap the refrigerant. The right call is Not allowed or safe; A2L equipment is designed and listed for it.", "No es Solo se cambia el refrigerante. La correcta es No está permitido ni es seguro; el equipo A2L se diseña y certifica para eso."), T("Not Change the oil and it's fine. The right call is Not allowed or safe; A2L equipment is designed and listed for it.", "No es Se cambia el aceite y listo. La correcta es No está permitido ni es seguro; el equipo A2L se diseña y certifica para eso."), T("Not It works if you add a filter-drier. The right call is Not allowed or safe; A2L equipment is designed and listed for it.", "No es Funciona con un filtro deshidratador. La correcta es No está permitido ni es seguro; el equipo A2L se diseña y certifica para eso.")], tip: T("There are no drop-ins. A2L equipment has listed safety features and charge limits.", "No hay reemplazos directos. El equipo A2L tiene seguridades certificadas y límites de carga.")});
  put("High superheat and low subcooling together most often mean:", {q: T("High superheat and low subcooling together most often mean?", "Sobrecalentamiento alto y subenfriamiento bajo juntos casi siempre indican:?"), a: [T("Low refrigerant charge", "Falta de refrigerante"), T("Overcharge", "Exceso de carga"), T("Dirty condenser", "Condensador sucio"), T("Too much indoor airflow only", "Solo demasiado aire interior")], c: 0, why: T("Not enough refrigerant starves the evaporator (high SH) and leaves little liquid in the condenser (low SC).", "Poco refrigerante deja hambriento al evaporador (SH alto) y poco líquido en el condensador (SC bajo)."), wrong: ["", T("Not Overcharge. The right call is Low refrigerant charge.", "No es Exceso de carga. La correcta es Falta de refrigerante."), T("Not Dirty condenser. The right call is Low refrigerant charge.", "No es Condensador sucio. La correcta es Falta de refrigerante."), T("Not Too much indoor airflow only. The right call is Low refrigerant charge.", "No es Solo demasiado aire interior. La correcta es Falta de refrigerante.")], tip: T("Not enough refrigerant starves the evaporator (high SH) and leaves little liquid in the condenser (low SC).", "Poco refrigerante deja hambriento al evaporador (SH alto) y poco líquido en el condensador (SC bajo).")});
