  put("Before recharging a system that had a leak, you should:", {q: T("Before recharging a system that had a leak, you should?", "Antes de recargar un sistema que tenía una fuga, debes:?"), a: [T("Repair, pressure-test and evacuate", "Reparar, probar con presión y hacer vacío"), T("Add dye and top off", "Agregar tinte y rellenar"), T("Just top it off", "Solo rellenar"), T("Replace the thermostat", "Cambiar el termostato")], c: 0, why: T("Topping off a known leak wastes refrigerant and may violate leak-repair rules on larger systems.", "Rellenar con una fuga conocida desperdicia refrigerante y puede violar reglas de reparación en sistemas grandes."), wrong: ["", T("Not Add dye and top off. The right call is Repair, pressure-test and evacuate.", "No es Agregar tinte y rellenar. La correcta es Reparar, probar con presión y hacer vacío."), T("Not Just top it off. The right call is Repair, pressure-test and evacuate.", "No es Solo rellenar. La correcta es Reparar, probar con presión y hacer vacío."), T("Not Replace the thermostat. The right call is Repair, pressure-test and evacuate.", "No es Cambiar el termostato. La correcta es Reparar, probar con presión y hacer vacío.")], tip: T("Topping off a known leak wastes refrigerant and may violate leak-repair rules on larger systems.", "Rellenar con una fuga conocida desperdicia refrigerante y puede violar reglas de reparación en sistemas grandes.")});
  put("A heat pump's outdoor coil stays iced and never clears. Check first:", {q: T("A heat pump's outdoor coil stays iced and never clears. Check first:", "La bobina exterior de una bomba de calor sigue con hielo y nunca se limpia. Revisa primero:"), a: [T("Defrost control, sensor and reversing valve", "Control de deshielo, sensor y válvula reversible"), T("The furnace flame sensor", "El sensor de flama"), T("Gas pressure", "La presión de gas"), T("Duct insulation", "El aislamiento de ductos")], c: 0, why: T("Defrost must initiate, shift the reversing valve and terminate. Low charge can also cause heavy icing.", "El deshielo debe iniciar, cambiar la válvula reversible y terminar. La falta de carga también causa mucho hielo."), wrong: ["", T("Not The furnace flame sensor. The right call is Defrost control, sensor and reversing valve.", "No es El sensor de flama. La correcta es Control de deshielo, sensor y válvula reversible."), T("Not Gas pressure. The right call is Defrost control, sensor and reversing valve.", "No es La presión de gas. La correcta es Control de deshielo, sensor y válvula reversible."), T("Not Duct insulation. The right call is Defrost control, sensor and reversing valve.", "No es El aislamiento de ductos. La correcta es Control de deshielo, sensor y válvula reversible.")], tip: T("Defrost must initiate, shift the reversing valve and terminate. Low charge can also cause heavy icing.", "El deshielo debe iniciar, cambiar la válvula reversible y terminar. La falta de carga también causa mucho hielo.")});
  put("After a compressor burnout, which step helps protect the new compressor?", {q: T("After a compressor burnout, which step helps protect the new compressor?", "Tras quemarse un compresor, ¿qué paso protege al nuevo?"), a: [T("Acid test plus suction and liquid filter-driers", "Prueba de ácido más filtros en succión y líquido"), T("Reuse the old drier", "Reusar el filtro viejo"), T("Skip evacuation to save time", "Saltar el vacío para ahorrar tiempo"), T("Overcharge slightly", "Sobrecargar un poco")], c: 0, why: T("Acid and debris from a burnout will kill the replacement unless they are cleaned up.", "El ácido y la basura de un compresor quemado matan al nuevo si no se limpian."), wrong: ["", T("Not Reuse the old drier. The right call is Acid test plus suction and liquid filter-driers.", "No es Reusar el filtro viejo. La correcta es Prueba de ácido más filtros en succión y líquido."), T("Not Skip evacuation to save time. The right call is Acid test plus suction and liquid filter-driers.", "No es Saltar el vacío para ahorrar tiempo. La correcta es Prueba de ácido más filtros en succión y líquido."), T("Not Overcharge slightly. The right call is Acid test plus suction and liquid filter-driers.", "No es Sobrecargar un poco. La correcta es Prueba de ácido más filtros en succión y líquido.")], tip: T("Acid and debris from a burnout will kill the replacement unless they are cleaned up.", "El ácido y la basura de un compresor quemado matan al nuevo si no se limpian.")});
  put("What does an air conditioner actually do?", {q: T("What does an air conditioner actually do?", "¿Qué hace en realidad un aire acondicionado?"), a: [T("Moves heat from inside to outside", "Mueve calor de adentro hacia afuera"), T("Makes cold air from nothing", "Fabrica aire frío de la nada"), T("Adds cold refrigerant to your air", "Le agrega refrigerante frío al aire"), T("Pulls fresh air in from outside", "Mete aire fresco de afuera")], c: 0, why: T("Heat is picked up indoors and released outdoors. Cold is just less heat.", "El calor se recoge adentro y se suelta afuera. El frío es solo menos calor."), wrong: ["", T("Not Makes cold air from nothing. The right call is Moves heat from inside to outside.", "No es Fabrica aire frío de la nada. La correcta es Mueve calor de adentro hacia afuera."), T("Not Adds cold refrigerant to your air. The right call is Moves heat from inside to outside.", "No es Le agrega refrigerante frío al aire. La correcta es Mueve calor de adentro hacia afuera."), T("Not Pulls fresh air in from outside. The right call is Moves heat from inside to outside.", "No es Mete aire fresco de afuera. La correcta es Mueve calor de adentro hacia afuera.")], tip: T("Heat is picked up indoors and released outdoors. Cold is just less heat.", "El calor se recoge adentro y se suelta afuera. El frío es solo menos calor.")});
