  put("How does a heat pump warm a house in winter?", {q: T("How does a heat pump warm a house in winter?", "¿Cómo calienta una casa una bomba de calor en invierno?"), a: [T("It moves heat from the outdoor air indoors", "Mueve calor del aire de afuera hacia adentro"), T("It burns natural gas", "Quema gas natural"), T("It only runs a space heater", "Solo prende un calentador"), T("It cannot heat at all", "No puede calentar")], c: 0, why: T("A reversing valve flips the flow so the outdoor coil gathers heat and the indoor coil releases it.", "Una válvula de inversión cambia el flujo: el serpentín de afuera junta calor y el de adentro lo suelta."), wrong: ["", T("Not It burns natural gas. The right call is It moves heat from the outdoor air indoors.", "No es Quema gas natural. La correcta es Mueve calor del aire de afuera hacia adentro."), T("Not It only runs a space heater. The right call is It moves heat from the outdoor air indoors.", "No es Solo prende un calentador. La correcta es Mueve calor del aire de afuera hacia adentro."), T("Not It cannot heat at all. The right call is It moves heat from the outdoor air indoors.", "No es No puede calentar. La correcta es Mueve calor del aire de afuera hacia adentro.")], tip: T("A reversing valve flips the flow so the outdoor coil gathers heat and the indoor coil releases it.", "Una válvula de inversión cambia el flujo: el serpentín de afuera junta calor y el de adentro lo suelta.")});
