  put("What does the fan 'Auto' setting do?", {q: T("What does the fan 'Auto' setting do?", "¿Qué hace el ajuste 'Auto' del ventilador?"), a: [T("Runs the blower only while heating or cooling", "Prende el soplador solo cuando calienta o enfría"), T("Runs the blower all day", "Prende el soplador todo el día"), T("Turns the heat on automatically", "Prende la calefacción sola"), T("Shuts the system off", "Apaga el sistema")], c: 0, why: T("Auto ties the fan to the heating or cooling call. On runs it nonstop.", "Auto liga el ventilador al calor o al frío. On lo deja prendido siempre."), wrong: ["", T("Not Runs the blower all day. The right call is Runs the blower only while heating or cooling.", "No es Prende el soplador todo el día. La correcta es Prende el soplador solo cuando calienta o enfría."), T("Not Turns the heat on automatically. The right call is Runs the blower only while heating or cooling.", "No es Prende la calefacción sola. La correcta es Prende el soplador solo cuando calienta o enfría."), T("Not Shuts the system off. The right call is Runs the blower only while heating or cooling.", "No es Apaga el sistema. La correcta es Prende el soplador solo cuando calienta o enfría.")], tip: T("Auto ties the fan to the heating or cooling call. On runs it nonstop.", "Auto liga el ventilador al calor o al frío. On lo deja prendido siempre.")});
