  put("Which way should the arrow on the filter point?", {q: T("Which way should the arrow on the filter point?", "¿Hacia dónde debe apuntar la flecha del filtro?"), a: [T("Toward the furnace or blower", "Hacia el calefactor o soplador"), T("Toward the return grille", "Hacia la rejilla de retorno"), T("Up, always", "Siempre hacia arriba"), T("It does not matter", "No importa")], c: 0, why: T("The arrow shows airflow direction: into the equipment.", "La flecha indica la dirección del aire: hacia el equipo."), wrong: ["", T("Not Toward the return grille. The right call is Toward the furnace or blower.", "No es Hacia la rejilla de retorno. La correcta es Hacia el calefactor o soplador."), T("Not Up, always. The right call is Toward the furnace or blower.", "No es Siempre hacia arriba. La correcta es Hacia el calefactor o soplador."), T("Not It does not matter. The right call is Toward the furnace or blower.", "No es No importa. La correcta es Hacia el calefactor o soplador.")], tip: T("The arrow shows airflow direction: into the equipment.", "La flecha indica la dirección del aire: hacia el equipo.")});
