  put("Which refrigerant type has the highest ozone depletion potential?", {q: T("Which refrigerant type has the highest ozone depletion potential?", "¿Qué tipo de refrigerante tiene el mayor potencial de agotamiento de ozono?"), a: [T("CFC", "CFC"), T("HCFC", "HCFC"), T("HFC", "HFC"), T("HFO", "HFO")], c: 0, why: T("CFCs (like R-12) contain the most chlorine and are very stable, so they reach the stratosphere. HCFCs are lower; HFCs and HFOs have zero ODP.", "Los CFC (como el R-12) tienen más cloro y son muy estables, así que llegan a la estratosfera. Los HCFC tienen menos; los HFC y HFO tienen ODP cero."), wrong: ["", T("Not HCFC. The right call is CFC.", "No es HCFC. La correcta es CFC."), T("Not HFC. The right call is CFC.", "No es HFC. La correcta es CFC."), T("Not HFO. The right call is CFC.", "No es HFO. La correcta es CFC.")], tip: T("CFCs (like R-12) contain the most chlorine and are very stable, so they reach the stratosphere. HCFCs are lower; HFCs and HFOs have zero ODP. (Background — Subpart F purpose)", "Los CFC (como el R-12) tienen más cloro y son muy estables, así que llegan a la estratosfera. Los HCFC tienen menos; los HFC y HFO tienen ODP cero. (Background — Subpart F purpose)")});
  put("Which element in CFCs and HCFCs destroys stratospheric ozone?", {q: T("Which element in CFCs and HCFCs destroys stratospheric ozone?", "¿Qué elemento de los CFC y HCFC destruye el ozono estratosférico?"), a: [T("Chlorine", "Cloro"), T("Fluorine", "Flúor"), T("Hydrogen", "Hidrógeno"), T("Carbon", "Carbono")], c: 0, why: T("UV light frees chlorine atoms, and one chlorine atom can break down many ozone molecules.", "La luz UV libera átomos de cloro, y un solo átomo de cloro puede destruir muchas moléculas de ozono."), wrong: ["", T("Not Fluorine. The right call is Chlorine.", "No es Flúor. La correcta es Cloro."), T("Not Hydrogen. The right call is Chlorine.", "No es Hidrógeno. La correcta es Cloro."), T("Not Carbon. The right call is Chlorine.", "No es Carbono. La correcta es Cloro.")], tip: T("UV light frees chlorine atoms, and one chlorine atom can break down many ozone molecules. (Background)", "La luz UV libera átomos de cloro, y un solo átomo de cloro puede destruir muchas moléculas de ozono. (Background)")});
  put("Which international agreement set the phaseout of ozone-depleting substances?", {q: T("Which international agreement set the phaseout of ozone-depleting substances?", "¿Qué acuerdo internacional estableció la eliminación de sustancias que agotan el ozono?"), a: [T("Montreal Protocol", "Protocolo de Montreal"), T("Kyoto Protocol", "Protocolo de Kioto"), T("Paris Agreement", "Acuerdo de París"), T("Geneva Accord", "Acuerdo de Ginebra")], c: 0, why: T("The 1987 Montreal Protocol led to the U.S. phaseout rules under the Clean Air Act.", "El Protocolo de Montreal de 1987 llevó a las reglas de eliminación en EE. UU. bajo la Ley de Aire Limpio."), wrong: ["", T("Not Kyoto Protocol. The right call is Montreal Protocol.", "No es Protocolo de Kioto. La correcta es Protocolo de Montreal."), T("Not Paris Agreement. The right call is Montreal Protocol.", "No es Acuerdo de París. La correcta es Protocolo de Montreal."), T("Not Geneva Accord. The right call is Montreal Protocol.", "No es Acuerdo de Ginebra. La correcta es Protocolo de Montreal.")], tip: T("The 1987 Montreal Protocol led to the U.S. phaseout rules under the Clean Air Act. (Background)", "El Protocolo de Montreal de 1987 llevó a las reglas de eliminación en EE. UU. bajo la Ley de Aire Limpio. (Background)")});
  put("Refrigerant cleaned to the AHRI 700 standard and verified by lab analysis is called:", {q: T("Refrigerant cleaned to the AHRI 700 standard and verified by lab analysis is called?", "El refrigerante limpiado al estándar AHRI 700 y verificado en laboratorio se llama?"), a: [T("Reclaimed", "Regenerado"), T("Recovered", "Recuperado"), T("Recycled", "Reciclado"), T("Virgin", "Virgen")], c: 0, why: T("Recover = remove and store. Recycle = clean for reuse (oil separation, filter-driers). Reclaim = reprocess to AHRI 700 purity, proven by chemical analysis.", "Recuperar = sacar y guardar. Reciclar = limpiar para reusar. Regenerar = reprocesar a la pureza AHRI 700, comprobada por análisis químico."), wrong: ["", T("Not Recovered. The right call is Reclaimed.", "No es Recuperado. La correcta es Regenerado."), T("Not Recycled. The right call is Reclaimed.", "No es Reciclado. La correcta es Regenerado."), T("Not Virgin. The right call is Reclaimed.", "No es Virgen. La correcta es Regenerado.")], tip: T("Recover = remove and store. Recycle = clean for reuse (oil separation, filter-driers). Reclaim = reprocess to AHRI 700 purity, proven by chemical analysis. (40 CFR 82.152 (definitions))", "Recuperar = sacar y guardar. Reciclar = limpiar para reusar. Regenerar = reprocesar a la pureza AHRI 700, comprobada por análisis químico. (40 CFR 82.152 (definitions))")});
  put("Used refrigerant going to a DIFFERENT owner's equipment must first be:", {q: T("Used refrigerant going to a DIFFERENT owner's equipment must first be?", "El refrigerante usado que irá al equipo de OTRO dueño primero debe ser?"), a: [T("Reclaimed by a certified reclaimer", "Regenerado por un regenerador certificado"), T("Filtered once", "Filtrado una vez"), T("Mixed with new refrigerant", "Mezclado con refrigerante nuevo"), T("Nothing — it can be sold as is", "Nada, se puede vender así")], c: 0, why: T("Recovered refrigerant may go back into the same system or another system with the same owner. Selling it to a new owner requires reclamation.", "El refrigerante recuperado puede volver al mismo sistema u otro del mismo dueño. Venderlo a otro dueño requiere regeneración."), wrong: ["", T("Not Filtered once. The right call is Reclaimed by a certified reclaimer.", "No es Filtrado una vez. La correcta es Regenerado por un regenerador certificado."), T("Not Mixed with new refrigerant. The right call is Reclaimed by a certified reclaimer.", "No es Mezclado con refrigerante nuevo. La correcta es Regenerado por un regenerador certificado."), T("Not Nothing — it can be sold as is. The right call is Reclaimed by a certified reclaimer.", "No es Nada, se puede vender así. La correcta es Regenerado por un regenerador certificado.")], tip: T("Recovered refrigerant may go back into the same system or another system with the same owner. Selling it to a new owner requires reclamation. (40 CFR 82.154, 82.164)", "El refrigerante recuperado puede volver al mismo sistema u otro del mismo dueño. Venderlo a otro dueño requiere regeneración. (40 CFR 82.154, 82.164)")});
  put("Who may buy most regulated refrigerants (other than small MVAC cans) under Subpart F?", {q: T("Who may buy most regulated refrigerants (other than small MVAC cans) under Subpart F?", "¿Quién puede comprar la mayoría de refrigerantes regulados (salvo latas pequeñas MVAC) según la Subparte F?"), a: [T("Certified technicians (or businesses employing them)", "Técnicos certificados (o empresas que los emplean)"), T("Anyone over 18", "Cualquier mayor de 18 años"), T("Only reclaimers", "Solo regeneradores"), T("Only manufacturers", "Solo fabricantes")], c: 0, why: T("The sales restriction limits refrigerant sales to properly certified technicians, with limited exceptions.", "La restricción de venta limita la venta de refrigerante a técnicos debidamente certificados, con pocas excepciones."), wrong: ["", T("Not Anyone over 18. The right call is Certified technicians (or businesses employing them).", "No es Cualquier mayor de 18 años. La correcta es Técnicos certificados (o empresas que los emplean)."), T("Not Only reclaimers. The right call is Certified technicians (or businesses employing them).", "No es Solo regeneradores. La correcta es Técnicos certificados (o empresas que los emplean)."), T("Not Only manufacturers. The right call is Certified technicians (or businesses employing them).", "No es Solo fabricantes. La correcta es Técnicos certificados (o empresas que los emplean).")], tip: T("The sales restriction limits refrigerant sales to properly certified technicians, with limited exceptions. (40 CFR 82.154(c))", "La restricción de venta limita la venta de refrigerante a técnicos debidamente certificados, con pocas excepciones. (40 CFR 82.154(c))")});
  put("Recovery cylinders are usually painted:", {q: T("Recovery cylinders are usually painted?", "Los cilindros de recuperación normalmente están pintados?"), a: [T("Gray with a yellow top", "Gris con la parte superior amarilla"), T("Solid green", "Verde completo"), T("Red with white top", "Rojo con parte superior blanca"), T("Light blue", "Azul claro")], c: 0, why: T("Gray body / yellow shoulder identifies recovery (used refrigerant) cylinders. They must be DOT-approved and refillable.", "Cuerpo gris y hombro amarillo identifican cilindros de recuperación. Deben estar aprobados por DOT y ser rellenables."), wrong: ["", T("Not Solid green. The right call is Gray with a yellow top.", "No es Verde completo. La correcta es Gris con la parte superior amarilla."), T("Not Red with white top. The right call is Gray with a yellow top.", "No es Rojo con parte superior blanca. La correcta es Gris con la parte superior amarilla."), T("Not Light blue. The right call is Gray with a yellow top.", "No es Azul claro. La correcta es Gris con la parte superior amarilla.")], tip: T("Gray body / yellow shoulder identifies recovery (used refrigerant) cylinders. They must be DOT-approved and refillable. (Industry standard (AHRI Guideline N))", "Cuerpo gris y hombro amarillo identifican cilindros de recuperación. Deben estar aprobados por DOT y ser rellenables. (Industry standard (AHRI Guideline N))")});
  put("Which gas should be used to pressurize a system for leak testing?", {q: T("Which gas should be used to pressurize a system for leak testing?", "¿Qué gas se debe usar para presurizar un sistema en una prueba de fugas?"), a: [T("Dry nitrogen", "Nitrógeno seco"), T("Oxygen", "Oxígeno"), T("Compressed air", "Aire comprimido"), T("Acetylene", "Acetileno")], c: 0, why: T("Oxygen or air with compressor oil can explode. Use dry nitrogen with a regulator and relief valve. A small trace of HCFC-22 may be added for electronic detection.", "El oxígeno o aire con aceite del compresor pueden explotar. Usa nitrógeno seco con regulador y válvula de alivio. Puede agregarse una pequeña traza de HCFC-22 para detección electrónica."), wrong: ["", T("Oxygen and oil can explode. That answer is a safety no.", "El oxígeno y el aceite pueden explotar. Esa respuesta es un no de seguridad."), T("Not Compressed air. The right call is Dry nitrogen.", "No es Aire comprimido. La correcta es Nitrógeno seco."), T("Not Acetylene. The right call is Dry nitrogen.", "No es Acetileno. La correcta es Nitrógeno seco.")], tip: T("Oxygen or air with compressor oil can explode. Use dry nitrogen with a regulator and relief valve. A small trace of HCFC-22 may be added for electronic detection. (Safety practice)", "El oxígeno o aire con aceite del compresor pueden explotar. Usa nitrógeno seco con regulador y válvula de alivio. Puede agregarse una pequeña traza de HCFC-22 para detección electrónica. (Safety practice)")});
  put("Why is moisture harmful in a refrigeration system?", {q: T("Why is moisture harmful in a refrigeration system?", "¿Por qué la humedad es dañina en un sistema de refrigeración?"), a: [T("It can form acids and freeze in the metering device", "Puede formar ácidos y congelarse en el dispositivo de expansión"), T("It raises efficiency", "Aumenta la eficiencia"), T("It lubricates the compressor", "Lubrica el compresor"), T("It has no effect", "No tiene efecto")], c: 0, why: T("Moisture reacts with refrigerant and oil to form acids, and ice can block small orifices. A deep vacuum (dehydration) removes it.", "La humedad reacciona con refrigerante y aceite formando ácidos, y el hielo puede tapar orificios pequeños. Un vacío profundo (deshidratación) la elimina."), wrong: ["", T("Not It raises efficiency. The right call is It can form acids and freeze in the metering device.", "No es Aumenta la eficiencia. La correcta es Puede formar ácidos y congelarse en el dispositivo de expansión."), T("Not It lubricates the compressor. The right call is It can form acids and freeze in the metering device.", "No es Lubrica el compresor. La correcta es Puede formar ácidos y congelarse en el dispositivo de expansión."), T("Not It has no effect. The right call is It can form acids and freeze in the metering device.", "No es No tiene efecto. La correcta es Puede formar ácidos y congelarse en el dispositivo de expansión.")], tip: T("Moisture reacts with refrigerant and oil to form acids, and ice can block small orifices. A deep vacuum (dehydration) removes it. (Service practice)", "La humedad reacciona con refrigerante y aceite formando ácidos, y el hielo puede tapar orificios pequeños. Un vacío profundo (deshidratación) la elimina. (Service practice)")});
