  put("A zeotropic blend (400-series) should usually be charged as:", {q: T("A zeotropic blend (400-series) should usually be charged as?", "Una mezcla zeotrópica (serie 400) normalmente debe cargarse como?"), a: [T("Liquid, to avoid fractionation", "Líquido, para evitar fraccionamiento"), T("Vapor only", "Solo vapor"), T("Either, it doesn't matter", "Cualquiera, no importa"), T("Frozen solid", "Sólido congelado")], c: 0, why: T("Components boil off at different rates. Charging liquid keeps the blend's mix correct. Meter liquid into the low side slowly to protect the compressor.", "Los componentes se evaporan a distinto ritmo. Cargar líquido mantiene la mezcla correcta. Dosifica el líquido lentamente en el lado bajo para proteger el compresor."), wrong: ["", T("Not Vapor only. The right call is Liquid, to avoid fractionation.", "No es Solo vapor. La correcta es Líquido, para evitar fraccionamiento."), T("Not Either, it doesn't matter. The right call is Liquid, to avoid fractionation.", "No es Cualquiera, no importa. La correcta es Líquido, para evitar fraccionamiento."), T("Not Frozen solid. The right call is Liquid, to avoid fractionation.", "No es Sólido congelado. La correcta es Líquido, para evitar fraccionamiento.")], tip: T("Components boil off at different rates. Charging liquid keeps the blend's mix correct. Meter liquid into the low side slowly to protect the compressor. (Service practice)", "Los componentes se evaporan a distinto ritmo. Cargar líquido mantiene la mezcla correcta. Dosifica el líquido lentamente en el lado bajo para proteger el compresor. (Service practice)")});
  put("Temperature glide is a property of:", {q: T("Temperature glide is a property of?", "El deslizamiento de temperatura es una propiedad de?"), a: [T("Zeotropic blends", "Mezclas zeotrópicas"), T("Azeotropic blends", "Mezclas azeotrópicas"), T("Single-component refrigerants", "Refrigerantes de un solo componente"), T("Water", "Agua")], c: 0, why: T("Zeotropes boil and condense over a temperature range at one pressure. Azeotropes (500-series) act like a single refrigerant.", "Las zeotrópicas hierven y condensan en un rango de temperatura a una presión. Las azeotrópicas (serie 500) se comportan como un solo refrigerante."), wrong: ["", T("Not Azeotropic blends. The right call is Zeotropic blends.", "No es Mezclas azeotrópicas. La correcta es Mezclas zeotrópicas."), T("Not Single-component refrigerants. The right call is Zeotropic blends.", "No es Refrigerantes de un solo componente. La correcta es Mezclas zeotrópicas."), T("Not Water. The right call is Zeotropic blends.", "No es Agua. La correcta es Mezclas zeotrópicas.")], tip: T("Zeotropes boil and condense over a temperature range at one pressure. Azeotropes (500-series) act like a single refrigerant. (Background)", "Las zeotrópicas hierven y condensan en un rango de temperatura a una presión. Las azeotrópicas (serie 500) se comportan como un solo refrigerante. (Background)")});
