  put("Using recovery equipment made after Nov. 15, 1993, on a small appliance whose compressor does NOT run, you must recover:", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). Using recovery equipment made after Nov. 15, 1993, on a small appliance whose compressor does NOT run, you must recover?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). Con equipo posterior al 15 nov. 1993, en un aparato pequeño cuyo compresor NO funciona, debes recuperar?"), a: [T("80% of the charge (or reach 4 in. Hg vacuum)", "80% de la carga (o llegar a 4 in Hg)"), T("90%", "90%"), T("50%", "50%"), T("Nothing, it's broken", "Nada, está descompuesto")], c: 0, why: T("Non-working compressor: 80%. Working compressor: 90%. Or evacuate to 4 inches of mercury vacuum either way.", "Compresor que no funciona: 80%. Que sí funciona: 90%. O evacuar a 4 pulgadas de mercurio en ambos casos."), wrong: ["", T("Not 90%. The right call is 80% of the charge (or reach 4 in. Hg vacuum).", "No es 90%. La correcta es 80% de la carga (o llegar a 4 in Hg)."), T("Not 50%. The right call is 80% of the charge (or reach 4 in. Hg vacuum).", "No es 50%. La correcta es 80% de la carga (o llegar a 4 in Hg)."), T("Not Nothing, it's broken. The right call is 80% of the charge (or reach 4 in. Hg vacuum).", "No es Nada, está descompuesto. La correcta es 80% de la carga (o llegar a 4 in Hg).")], tip: T("Non-working compressor: 80%. Working compressor: 90%. Or evacuate to 4 inches of mercury vacuum either way. (40 CFR 82.156(b)(2))", "Compresor que no funciona: 80%. Que sí funciona: 90%. O evacuar a 4 pulgadas de mercurio en ambos casos. (40 CFR 82.156(b)(2))")});
  put("With recovery equipment made BEFORE Nov. 15, 1993, a small appliance requires:", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). With recovery equipment made BEFORE Nov. 15, 1993, a small appliance requires?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). Con equipo fabricado ANTES del 15 nov. 1993, un aparato pequeño requiere?"), a: [T("80% recovery (or 4 in. Hg vacuum)", "Recuperar 80% (o 4 in Hg de vacío)"), T("90% recovery", "Recuperar 90%"), T("100% recovery", "Recuperar 100%"), T("No recovery", "No recuperar")], c: 0, why: T("Older equipment: 80% regardless of compressor condition, or the 4 in. Hg vacuum option.", "Equipo viejo: 80% sin importar el compresor, o la opción de 4 in Hg."), wrong: ["", T("Not 90% recovery. The right call is 80% recovery (or 4 in. Hg vacuum).", "No es Recuperar 90%. La correcta es Recuperar 80% (o 4 in Hg de vacío)."), T("Not 100% recovery. The right call is 80% recovery (or 4 in. Hg vacuum).", "No es Recuperar 100%. La correcta es Recuperar 80% (o 4 in Hg de vacío)."), T("Not No recovery. The right call is 80% recovery (or 4 in. Hg vacuum).", "No es No recuperar. La correcta es Recuperar 80% (o 4 in Hg de vacío).")], tip: T("Older equipment: 80% regardless of compressor condition, or the 4 in. Hg vacuum option. (40 CFR 82.156(b)(1))", "Equipo viejo: 80% sin importar el compresor, o la opción de 4 in Hg. (40 CFR 82.156(b)(1))")});
  put("Which of these is a 'small appliance' under Subpart F?", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). Which is a 'small appliance' under Subpart F?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). ¿Cuál de estos es un 'aparato pequeño' según la Subparte F?"), a: [T("A window air conditioner with 1.5 lb of R-410A", "Un aire de ventana con 1.5 lb de R-410A"), T("A 3-ton split system", "Un sistema dividido de 3 toneladas"), T("A car's AC", "El aire de un carro"), T("A 200-ton chiller", "Un chiller de 200 toneladas")], c: 0, why: T("Factory-sealed with 5 lb or less. Field-piped splits are Type II; car AC is MVAC (Subpart B).", "Sellado de fábrica con 5 lb o menos. Los divididos instalados en campo son Tipo II; el aire del carro es MVAC (Subparte B)."), wrong: ["", T("Not A 3-ton split system. The right call is A window air conditioner with 1.5 lb of R-410A.", "No es Un sistema dividido de 3 toneladas. La correcta es Un aire de ventana con 1.5 lb de R-410A."), T("Not A car's AC. The right call is A window air conditioner with 1.5 lb of R-410A.", "No es El aire de un carro. La correcta es Un aire de ventana con 1.5 lb de R-410A."), T("Not A 200-ton chiller. The right call is A window air conditioner with 1.5 lb of R-410A.", "No es Un chiller de 200 toneladas. La correcta es Un aire de ventana con 1.5 lb de R-410A.")], tip: T("Factory-sealed with 5 lb or less. Field-piped splits are Type II; car AC is MVAC (Subpart B). (40 CFR 82.152)", "Sellado de fábrica con 5 lb o menos. Los divididos instalados en campo son Tipo II; el aire del carro es MVAC (Subparte B). (40 CFR 82.152)")});
  put("Who is responsible for refrigerant removal when a refrigerator reaches the scrap yard?", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). Who is responsible for refrigerant removal when a refrigerator reaches the scrap yard?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). ¿Quién es responsable de quitar el refrigerante cuando un refrigerador llega al deshuesadero?"), a: [T("The final processor, who recovers it or verifies it was recovered", "El procesador final, que lo recupera o verifica que se recuperó"), T("Nobody, it's scrap", "Nadie, es chatarra"), T("The original manufacturer", "El fabricante original"), T("The homeowner only", "Solo el dueño de la casa")], c: 0, why: T("The final processor must recover the refrigerant or get a signed statement or contract saying it was already recovered.", "El procesador final debe recuperarlo o pedir una declaración firmada o contrato de que ya se recuperó."), wrong: ["", T("Not Nobody, it's scrap. The right call is The final processor, who recovers it or verifies it was recovered.", "No es Nadie, es chatarra. La correcta es El procesador final, que lo recupera o verifica que se recuperó."), T("Not The original manufacturer. The right call is The final processor, who recovers it or verifies it was recovered.", "No es El fabricante original. La correcta es El procesador final, que lo recupera o verifica que se recuperó."), T("Not The homeowner only. The right call is The final processor, who recovers it or verifies it was recovered.", "No es Solo el dueño de la casa. La correcta es El procesador final, que lo recupera o verifica que se recuperó.")], tip: T("The final processor must recover the refrigerant or get a signed statement or contract saying it was already recovered. (40 CFR 82.155(b))", "El procesador final debe recuperarlo o pedir una declaración firmada o contrato de que ya se recuperó. (40 CFR 82.155(b))")});
  put("A signed statement verifying refrigerant was recovered before disposal must include:", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). A signed statement verifying refrigerant was recovered before disposal must include?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). La declaración firmada de que se recuperó el refrigerante antes del desecho debe incluir?"), a: [T("Name and address of who recovered it, and the date", "Nombre y dirección de quien lo recuperó, y la fecha"), T("Only the appliance color", "Solo el color del aparato"), T("The refrigerant price", "El precio del refrigerante"), T("A photo of the tech", "Una foto del técnico")], c: 0, why: T("Statements need the recoverer's name, address and recovery date. Disposal records are kept three years.", "Debe llevar nombre, dirección y fecha de quien recuperó. Los registros de desecho se guardan tres años."), wrong: ["", T("Not Only the appliance color. The right call is Name and address of who recovered it, and the date.", "No es Solo el color del aparato. La correcta es Nombre y dirección de quien lo recuperó, y la fecha."), T("Not The refrigerant price. The right call is Name and address of who recovered it, and the date.", "No es El precio del refrigerante. La correcta es Nombre y dirección de quien lo recuperó, y la fecha."), T("Not A photo of the tech. The right call is Name and address of who recovered it, and the date.", "No es Una foto del técnico. La correcta es Nombre y dirección de quien lo recuperó, y la fecha.")], tip: T("Statements need the recoverer's name, address and recovery date. Disposal records are kept three years. (40 CFR 82.155(b)–(c))", "Debe llevar nombre, dirección y fecha de quien recuperó. Los registros de desecho se guardan tres años. (40 CFR 82.155(b)–(c))")});
  put("Which refrigerant may be vented from a household refrigerator without violating the venting prohibition?", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). Which refrigerant may be vented from a household refrigerator without violating the venting prohibition?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). ¿Qué refrigerante se puede ventear de un refrigerador doméstico sin violar la prohibición?"), a: [T("Isobutane (R-600a)", "Isobutano (R-600a)"), T("R-134a", "R-134a"), T("R-12", "R-12"), T("R-22", "R-22")], c: 0, why: T("R-600a, R-290 and R-441A are exempt substitutes in household refrigerators. They're flammable, so ventilate and keep ignition sources away.", "R-600a, R-290 y R-441A son sustitutos exentos en refrigeradores domésticos. Son inflamables: ventila y aleja fuentes de chispa."), wrong: ["", T("Not R-134a. The right call is Isobutane (R-600a).", "No es R-134a. La correcta es Isobutano (R-600a)."), T("Not R-12. The right call is Isobutane (R-600a).", "No es R-12. La correcta es Isobutano (R-600a)."), T("Not R-22. The right call is Isobutane (R-600a).", "No es R-22. La correcta es Isobutano (R-600a).")], tip: T("R-600a, R-290 and R-441A are exempt substitutes in household refrigerators. They're flammable, so ventilate and keep ignition sources away. (40 CFR 82.154(a)(1)(viii)–(x))", "R-600a, R-290 y R-441A son sustitutos exentos en refrigeradores domésticos. Son inflamables: ventila y aleja fuentes de chispa. (40 CFR 82.154(a)(1)(viii)–(x))")});
