  put("The 'process stub' on a small appliance is:", {q: T("You're on a small-appliance call (fridge, window unit, or dehumidifier). The 'process stub' on a small appliance is?", "Estás en una llamada de aparato pequeño (refri, ventana o deshumidificador). El 'tubo de proceso' de un aparato pequeño es?"), a: [T("A short tube used at the factory to charge the system", "Un tubo corto que se usa en fábrica para cargar el sistema"), T("A drain line", "Una línea de drenaje"), T("The power cord strain relief", "El protector del cable"), T("A thermostat sensor", "El sensor del termostato")], c: 0, why: T("It's usually where a piercing valve or a permanent access fitting goes for recovery and service.", "Ahí normalmente se pone la perforadora o un acceso permanente para recuperar y dar servicio."), wrong: ["", T("Not A drain line. The right call is A short tube used at the factory to charge the system.", "No es Una línea de drenaje. La correcta es Un tubo corto que se usa en fábrica para cargar el sistema."), T("Not The power cord strain relief. The right call is A short tube used at the factory to charge the system.", "No es El protector del cable. La correcta es Un tubo corto que se usa en fábrica para cargar el sistema."), T("Not A thermostat sensor. The right call is A short tube used at the factory to charge the system.", "No es El sensor del termostato. La correcta es Un tubo corto que se usa en fábrica para cargar el sistema.")], tip: T("It's usually where a piercing valve or a permanent access fitting goes for recovery and service. (Service practice)", "Ahí normalmente se pone la perforadora o un acceso permanente para recuperar y dar servicio. (Service practice)")});
  put("Owners of comfort-cooling appliances with 50+ lb of CFC/HCFC refrigerant must repair leaks when the leak rate exceeds:", {q: T("You're on a high-pressure split, RTU, or rack. Owners of comfort-cooling appliances with 50+ lb of CFC/HCFC refrigerant must repair leaks when the leak rate exceeds?", "Estás en un split, RTU o rack de alta presión. Los dueños de equipos de confort con 50+ lb de refrigerante CFC/HCFC deben reparar fugas cuando la tasa pasa de?"), a: [T("10%", "10%"), T("20%", "20%"), T("30%", "30%"), T("35%", "35%")], c: 0, why: T("Subpart F leak repair thresholds (ODS appliances 50 lb+): comfort cooling 10%, commercial refrigeration 20%, industrial process refrigeration 30%.", "Umbrales de la Subparte F (equipos con ODS de 50 lb+): confort 10%, refrigeración comercial 20%, refrigeración de procesos industriales 30%."), wrong: ["", T("Not 20%. The right call is 10%.", "No es 20%. La correcta es 10%."), T("Not 30%. The right call is 10%.", "No es 30%. La correcta es 10%."), T("Not 35%. The right call is 10%.", "No es 35%. La correcta es 10%.")], tip: T("Subpart F leak repair thresholds (ODS appliances 50 lb+): comfort cooling 10%, commercial refrigeration 20%, industrial process refrigeration 30%. (40 CFR 82.157(c))", "Umbrales de la Subparte F (equipos con ODS de 50 lb+): confort 10%, refrigeración comercial 20%, refrigeración de procesos industriales 30%. (40 CFR 82.157(c))")});
  put("After adding refrigerant to an appliance leaking above the threshold, repairs must generally be made within:", {q: T("You're on a high-pressure split, RTU, or rack. After adding refrigerant to an appliance leaking above the threshold, repairs must generally be made within?", "Estás en un split, RTU o rack de alta presión. Después de agregar refrigerante a un equipo que fuga arriba del umbral, la reparación debe hacerse por lo general en?"), a: [T("30 days", "30 días"), T("7 days", "7 días"), T("90 days", "90 días"), T("1 year", "1 año")], c: 0, why: T("30 days from when refrigerant is added (120 days if an industrial process shutdown is required).", "30 días desde que se agrega refrigerante (120 si se requiere paro de un proceso industrial)."), wrong: ["", T("Not 7 days. The right call is 30 days.", "No es 7 días. La correcta es 30 días."), T("Not 90 days. The right call is 30 days.", "No es 90 días. La correcta es 30 días."), T("Not 1 year. The right call is 30 days.", "No es 1 año. La correcta es 30 días.")], tip: T("30 days from when refrigerant is added (120 days if an industrial process shutdown is required). (40 CFR 82.157(d))", "30 días desde que se agrega refrigerante (120 si se requiere paro de un proceso industrial). (40 CFR 82.157(d))")});
