  put("To speed up recovery on a large system, it's best to:", {q: T("You're on a high-pressure split, RTU, or rack. To speed up recovery on a large system, it's best to?", "Estás en un split, RTU o rack de alta presión. Para acelerar la recuperación en un sistema grande, lo mejor es?"), a: [T("Recover liquid first", "Recuperar primero el líquido"), T("Recover vapor only", "Recuperar solo vapor"), T("Heat the recovery cylinder", "Calentar el cilindro de recuperación"), T("Use the smallest hoses", "Usar las mangueras más delgadas")], c: 0, why: T("Liquid moves far more refrigerant per minute. Pull liquid first (push-pull if the system allows), then finish with vapor.", "El líquido mueve mucho más refrigerante por minuto. Saca primero líquido (empuje-jale si se puede) y termina con vapor."), wrong: ["", T("Not Recover vapor only. The right call is Recover liquid first.", "No es Recuperar solo vapor. La correcta es Recuperar primero el líquido."), T("Not Heat the recovery cylinder. The right call is Recover liquid first.", "No es Calentar el cilindro de recuperación. La correcta es Recuperar primero el líquido."), T("Not Use the smallest hoses. The right call is Recover liquid first.", "No es Usar las mangueras más delgadas. La correcta es Recuperar primero el líquido.")], tip: T("Liquid moves far more refrigerant per minute. Pull liquid first (push-pull if the system allows), then finish with vapor. (Service practice)", "El líquido mueve mucho más refrigerante por minuto. Saca primero líquido (empuje-jale si se puede) y termina con vapor. (Service practice)")});
  put("Commercial refrigeration appliances with 50+ lb of CFC/HCFC must repair leaks above:", {q: T("You're on a high-pressure split, RTU, or rack. Commercial refrigeration appliances with 50+ lb of CFC/HCFC must repair leaks above?", "Estás en un split, RTU o rack de alta presión. Los equipos de refrigeración comercial con 50+ lb de CFC/HCFC deben reparar fugas arriba de?"), a: [T("20% per year", "20% al año"), T("10% per year", "10% al año"), T("30% per year", "30% al año"), T("5% per year", "5% al año")], c: 0, why: T("Commercial refrigeration (supermarkets, cold storage) uses the 20% threshold.", "La refrigeración comercial (supermercados, cámaras) usa el umbral de 20%."), wrong: ["", T("Not 10% per year. The right call is 20% per year.", "No es 10% al año. La correcta es 20% al año."), T("Not 30% per year. The right call is 20% per year.", "No es 30% al año. La correcta es 20% al año."), T("Not 5% per year. The right call is 20% per year.", "No es 5% al año. La correcta es 20% al año.")], tip: T("Commercial refrigeration (supermarkets, cold storage) uses the 20% threshold. (40 CFR 82.157(c)(2))", "La refrigeración comercial (supermercados, cámaras) usa el umbral de 20%. (40 CFR 82.157(c)(2))")});
  put("A 'high-pressure appliance' uses a refrigerant whose liquid saturation pressure at 104°F is:", {q: T("You're on a high-pressure split, RTU, or rack. A 'high-pressure appliance' uses a refrigerant whose liquid saturation pressure at 104°F is?", "Estás en un split, RTU o rack de alta presión. Un 'aparato de alta presión' usa refrigerante con presión de saturación líquida a 104°F de?"), a: [T("170 to 355 psia", "170 a 355 psia"), T("Below 45 psia", "Menos de 45 psia"), T("45 to 170 psia", "45 a 170 psia"), T("Above 355 psia", "Más de 355 psia")], c: 0, why: T("Examples: R-22, R-407C, R-410A. Medium is 45–170 psia (R-134a); very high is above 355 psia or a critical temperature below 104°F (R-23).", "Ejemplos: R-22, R-407C, R-410A. Media: 45–170 psia (R-134a); muy alta: más de 355 psia o temperatura crítica bajo 104°F (R-23)."), wrong: ["", T("Not Below 45 psia. The right call is 170 to 355 psia.", "No es Menos de 45 psia. La correcta es 170 a 355 psia."), T("Not 45 to 170 psia. The right call is 170 to 355 psia.", "No es 45 a 170 psia. La correcta es 170 a 355 psia."), T("Not Above 355 psia. The right call is 170 to 355 psia.", "No es Más de 355 psia. La correcta es 170 a 355 psia.")], tip: T("Examples: R-22, R-407C, R-410A. Medium is 45–170 psia (R-134a); very high is above 355 psia or a critical temperature below 104°F (R-23). (40 CFR 82.152 (definitions))", "Ejemplos: R-22, R-407C, R-410A. Media: 45–170 psia (R-134a); muy alta: más de 355 psia o temperatura crítica bajo 104°F (R-23). (40 CFR 82.152 (definitions))")});
