  put("To change oil on a medium- or high-pressure appliance, you may open it after bringing pressure to no higher than:", {q: T("You're on a high-pressure split, RTU, or rack. To change oil on a medium- or high-pressure appliance, you may open it after bringing pressure to no higher than?", "Estás en un split, RTU o rack de alta presión. Para cambiar aceite en un equipo de media o alta presión, puedes abrirlo después de dejar la presión en no más de?"), a: [T("5 psig", "5 psig"), T("50 psig", "50 psig"), T("0 in. Hg only", "Solo 0 in Hg"), T("15 psig", "15 psig")], c: 0, why: T("Oil changes: evacuate or pressurize to no higher than 5 psig, or drain the oil into a system receiver at that pressure.", "Cambio de aceite: evacuar o presurizar a no más de 5 psig, o drenar el aceite a un recibidor a esa presión."), wrong: ["", T("Not 50 psig. The right call is 5 psig.", "No es 50 psig. La correcta es 5 psig."), T("Not 0 in. Hg only. The right call is 5 psig.", "No es Solo 0 in Hg. La correcta es 5 psig."), T("Not 15 psig. The right call is 5 psig.", "No es 15 psig. La correcta es 5 psig.")], tip: T("Oil changes: evacuate or pressurize to no higher than 5 psig, or drain the oil into a system receiver at that pressure. (40 CFR 82.156(a)(1)(iii))", "Cambio de aceite: evacuar o presurizar a no más de 5 psig, o drenar el aceite a un recibidor a esa presión. (40 CFR 82.156(a)(1)(iii))")});
  put("If leaks make the Table 1 level unreachable, the leaking component must be evacuated to:", {q: T("You're on a high-pressure split, RTU, or rack. If leaks make the Table 1 level unreachable, the leaking component must be evacuated to?", "Estás en un split, RTU o rack de alta presión. Si las fugas no permiten llegar a la Tabla 1, el componente que fuga se evacua a?"), a: [T("The lowest level attainable, not above 0 psig", "El nivel más bajo posible, no arriba de 0 psig"), T("Any pressure, it's leaking anyway", "Cualquier presión, ya está fugando"), T("15 psig", "15 psig"), T("Only the high side", "Solo el lado de alta")], c: 0, why: T("Isolate leaking from non-leaking sections, take the good ones to Table 1, and the leaking ones as low as possible without contaminating the refrigerant (max 0 psig).", "Aísla lo que fuga de lo que no, lleva lo bueno a la Tabla 1 y lo que fuga lo más bajo posible sin contaminar (máximo 0 psig)."), wrong: ["", T("Not Any pressure, it's leaking anyway. The right call is The lowest level attainable, not above 0 psig.", "No es Cualquier presión, ya está fugando. La correcta es El nivel más bajo posible, no arriba de 0 psig."), T("Not 15 psig. The right call is The lowest level attainable, not above 0 psig.", "No es 15 psig. La correcta es El nivel más bajo posible, no arriba de 0 psig."), T("Not Only the high side. The right call is The lowest level attainable, not above 0 psig.", "No es Solo el lado de alta. La correcta es El nivel más bajo posible, no arriba de 0 psig.")], tip: T("Isolate leaking from non-leaking sections, take the good ones to Table 1, and the leaking ones as low as possible without contaminating the refrigerant (max 0 psig). (40 CFR 82.156(a)(2))", "Aísla lo que fuga de lo que no, lleva lo bueno a la Tabla 1 y lo que fuga lo más bajo posible sin contaminar (máximo 0 psig). (40 CFR 82.156(a)(2))")});
  put("Industrial process refrigeration with 50+ lb of CFC/HCFC must repair leaks above:", {q: T("You're on a high-pressure split, RTU, or rack. Industrial process refrigeration with 50+ lb of CFC/HCFC must repair leaks above?", "Estás en un split, RTU o rack de alta presión. La refrigeración de procesos industriales con 50+ lb de CFC/HCFC debe reparar fugas arriba de?"), a: [T("30% per year", "30% al año"), T("10%", "10%"), T("20%", "20%"), T("50%", "50%")], c: 0, why: T("IPR has the highest threshold, 30%, and can get 120 days to repair if a process shutdown is needed.", "Los procesos industriales tienen el umbral más alto, 30%, y pueden tener 120 días si se requiere paro."), wrong: ["", T("Not 10%. The right call is 30% per year.", "No es 10%. La correcta es 30% al año."), T("Not 20%. The right call is 30% per year.", "No es 20%. La correcta es 30% al año."), T("Not 50%. The right call is 30% per year.", "No es 50%. La correcta es 30% al año.")], tip: T("IPR has the highest threshold, 30%, and can get 120 days to repair if a process shutdown is needed. (40 CFR 82.157(c)(2)(ii))", "Los procesos industriales tienen el umbral más alto, 30%, y pueden tener 120 días si se requiere paro. (40 CFR 82.157(c)(2)(ii))")});
  put("The 50-lb leak repair rules in 82.157 apply to appliances containing:", {q: T("You're on a high-pressure split, RTU, or rack. The 50-lb leak repair rules in 82.157 apply to appliances containing?", "Estás en un split, RTU o rack de alta presión. Las reglas de reparación de fugas de 50 lb (82.157) aplican a equipos que contienen?"), a: [T("Class I or II (CFC/HCFC) refrigerant or blends containing them", "Refrigerante Clase I o II (CFC/HCFC) o mezclas que los contengan"), T("Only HFOs", "Solo HFO"), T("Only R-410A", "Solo R-410A"), T("Any refrigerant", "Cualquier refrigerante")], c: 0, why: T("82.157 doesn't apply to appliances with solely substitute refrigerants. (HFC leak management is now under the AIM Act rules, 40 CFR Part 84.)", "La 82.157 no aplica a equipos solo con sustitutos. (El manejo de fugas de HFC ahora está en las reglas de la Ley AIM, 40 CFR Parte 84.)"), wrong: ["", T("Not Only HFOs. The right call is Class I or II (CFC/HCFC) refrigerant or blends containing them.", "No es Solo HFO. La correcta es Refrigerante Clase I o II (CFC/HCFC) o mezclas que los contengan."), T("Not Only R-410A. The right call is Class I or II (CFC/HCFC) refrigerant or blends containing them.", "No es Solo R-410A. La correcta es Refrigerante Clase I o II (CFC/HCFC) o mezclas que los contengan."), T("Not Any refrigerant. The right call is Class I or II (CFC/HCFC) refrigerant or blends containing them.", "No es Cualquier refrigerante. La correcta es Refrigerante Clase I o II (CFC/HCFC) o mezclas que los contengan.")], tip: T("82.157 doesn't apply to appliances with solely substitute refrigerants. (HFC leak management is now under the AIM Act rules, 40 CFR Part 84.) (40 CFR 82.157(a))", "La 82.157 no aplica a equipos solo con sustitutos. (El manejo de fugas de HFC ahora está en las reglas de la Ley AIM, 40 CFR Parte 84.) (40 CFR 82.157(a))")});
  put("After a leak repair on a 50+ lb ODS appliance, the repair must be documented with:", {q: T("You're on a high-pressure split, RTU, or rack. After a leak repair on a 50+ lb ODS appliance, the repair must be documented with?", "Estás en un split, RTU o rack de alta presión. Después de reparar una fuga en un equipo de 50+ lb con ODS, la reparación se documenta con?"), a: [T("Initial and follow-up verification tests", "Pruebas de verificación inicial y de seguimiento"), T("A photo of the coil", "Una foto del serpentín"), T("The customer's signature only", "Solo la firma del cliente"), T("Nothing", "Nada")], c: 0, why: T("Both an initial and a follow-up verification test are required to show the repair held.", "Se requieren una prueba de verificación inicial y una de seguimiento para demostrar que la reparación aguantó."), wrong: ["", T("Not A photo of the coil. The right call is Initial and follow-up verification tests.", "No es Una foto del serpentín. La correcta es Pruebas de verificación inicial y de seguimiento."), T("Not The customer's signature only. The right call is Initial and follow-up verification tests.", "No es Solo la firma del cliente. La correcta es Pruebas de verificación inicial y de seguimiento."), T("Not Nothing. The right call is Initial and follow-up verification tests.", "No es Nada. La correcta es Pruebas de verificación inicial y de seguimiento.")], tip: T("Both an initial and a follow-up verification test are required to show the repair held. (40 CFR 82.157(e))", "Se requieren una prueba de verificación inicial y una de seguimiento para demostrar que la reparación aguantó. (40 CFR 82.157(e))")});
  put("An ODS appliance (50+ lb) that leaks 125% or more of its full charge in a calendar year must be:", {q: T("You're on a high-pressure split, RTU, or rack. An ODS appliance (50+ lb) that leaks 125% or more of its full charge in a calendar year must be?", "Estás en un split, RTU o rack de alta presión. Un equipo con ODS (50+ lb) que fuga 125% o más de su carga en un año calendario debe?"), a: [T("Reported to EPA by March 1 of the next year", "Reportarse a la EPA antes del 1 de marzo del año siguiente"), T("Painted red", "Pintarse de rojo"), T("Ignored if repaired", "Ignorarse si se reparó"), T("Reported to the utility", "Reportarse a la compañía eléctrica")], c: 0, why: T("That's the chronically leaking appliance report, describing efforts to find and fix the leaks.", "Es el reporte de equipo con fuga crónica, describiendo lo que se hizo para encontrar y reparar."), wrong: ["", T("Not Painted red. The right call is Reported to EPA by March 1 of the next year.", "No es Pintarse de rojo. La correcta es Reportarse a la EPA antes del 1 de marzo del año siguiente."), T("Not Ignored if repaired. The right call is Reported to EPA by March 1 of the next year.", "No es Ignorarse si se reparó. La correcta es Reportarse a la EPA antes del 1 de marzo del año siguiente."), T("Not Reported to the utility. The right call is Reported to EPA by March 1 of the next year.", "No es Reportarse a la compañía eléctrica. La correcta es Reportarse a la EPA antes del 1 de marzo del año siguiente.")], tip: T("That's the chronically leaking appliance report, describing efforts to find and fix the leaks. (40 CFR 82.157(j))", "Es el reporte de equipo con fuga crónica, describiendo lo que se hizo para encontrar y reparar. (40 CFR 82.157(j))")});
  put("Mothballing an appliance (evacuated to at least atmospheric pressure and shut down) does what to leak-repair deadlines?", {q: T("You're on a high-pressure split, RTU, or rack. Mothballing an appliance (evacuated to at least atmospheric pressure and shut down) does what to leak-repair deadlines?", "Estás en un split, RTU o rack de alta presión. Poner un equipo en reposo (evacuado al menos a presión atmosférica y apagado) ¿qué hace con los plazos de reparación?"), a: [T("Pauses them until refrigerant is added again", "Los pausa hasta que se vuelva a agregar refrigerante"), T("Resets them to zero", "Los regresa a cero"), T("Cancels the requirement", "Cancela la obligación"), T("Shortens them to 7 days", "Los acorta a 7 días")], c: 0, why: T("Timeframes are suspended while mothballed and resume the day refrigerant is added back.", "Los plazos se suspenden mientras está en reposo y siguen el día que se agrega refrigerante."), wrong: ["", T("Not Resets them to zero. The right call is Pauses them until refrigerant is added again.", "No es Los regresa a cero. La correcta es Los pausa hasta que se vuelva a agregar refrigerante."), T("Not Cancels the requirement. The right call is Pauses them until refrigerant is added again.", "No es Cancela la obligación. La correcta es Los pausa hasta que se vuelva a agregar refrigerante."), T("Not Shortens them to 7 days. The right call is Pauses them until refrigerant is added again.", "No es Los acorta a 7 días. La correcta es Los pausa hasta que se vuelva a agregar refrigerante.")], tip: T("Timeframes are suspended while mothballed and resume the day refrigerant is added back. (40 CFR 82.157(d)(3))", "Los plazos se suspenden mientras está en reposo y siguen el día que se agrega refrigerante. (40 CFR 82.157(d)(3))")});
  put("Technicians disposing of appliances with more than 5 and less than 50 lb of refrigerant must keep records for:", {q: T("You're on a high-pressure split, RTU, or rack. Technicians disposing of appliances with more than 5 and less than 50 lb of refrigerant must keep records for?", "Estás en un split, RTU o rack de alta presión. Los técnicos que desechan equipos de más de 5 y menos de 50 lb deben guardar registros por?"), a: [T("3 years", "3 años"), T("1 year", "1 año"), T("6 months", "6 meses"), T("10 years", "10 años")], c: 0, why: T("Records include company, location, date, refrigerant type, monthly totals, and transfers for reclamation or destruction.", "Incluyen empresa, ubicación, fecha, tipo de refrigerante, totales mensuales y envíos a reclamación o destrucción."), wrong: ["", T("Not 1 year. The right call is 3 years.", "No es 1 año. La correcta es 3 años."), T("Not 6 months. The right call is 3 years.", "No es 6 meses. La correcta es 3 años."), T("Not 10 years. The right call is 3 years.", "No es 10 años. La correcta es 3 años.")], tip: T("Records include company, location, date, refrigerant type, monthly totals, and transfers for reclamation or destruction. (40 CFR 82.156(a)(3))", "Incluyen empresa, ubicación, fecha, tipo de refrigerante, totales mensuales y envíos a reclamación o destrucción. (40 CFR 82.156(a)(3))")});
  put("Who may service an 'MVAC-like' appliance (e.g., the AC on a farm tractor)?", {q: T("You're on a high-pressure split, RTU, or rack. Who may service an 'MVAC-like' appliance (e.g., the AC on a farm tractor)?", "Estás en un split, RTU o rack de alta presión. ¿Quién puede dar servicio a un aparato 'tipo MVAC' (p. ej. el aire de un tractor)?"), a: [T("A Type II tech, or someone certified under Subpart B", "Un técnico Tipo II, o alguien certificado bajo la Subparte B"), T("Type I only", "Solo Tipo I"), T("Type III only", "Solo Tipo III"), T("Anyone", "Cualquiera")], c: 0, why: T("MVAC-like appliances can be serviced with Type II certification or MVAC (Subpart B) certification.", "Los aparatos tipo MVAC se atienden con Tipo II o con certificación MVAC (Subparte B)."), wrong: ["", T("Not Type I only. The right call is A Type II tech, or someone certified under Subpart B.", "No es Solo Tipo I. La correcta es Un técnico Tipo II, o alguien certificado bajo la Subparte B."), T("Not Type III only. The right call is A Type II tech, or someone certified under Subpart B.", "No es Solo Tipo III. La correcta es Un técnico Tipo II, o alguien certificado bajo la Subparte B."), T("Not Anyone. The right call is A Type II tech, or someone certified under Subpart B.", "No es Cualquiera. La correcta es Un técnico Tipo II, o alguien certificado bajo la Subparte B.")], tip: T("MVAC-like appliances can be serviced with Type II certification or MVAC (Subpart B) certification. (40 CFR 82.161(a)(1)(v))", "Los aparatos tipo MVAC se atienden con Tipo II o con certificación MVAC (Subparte B). (40 CFR 82.161(a)(1)(v))")});
  put("A common sign of a refrigerant leak on a high-pressure system is:", {q: T("You're on a high-pressure split, RTU, or rack. A common sign of a refrigerant leak on a high-pressure system is?", "Estás en un split, RTU o rack de alta presión. Una señal común de fuga en un sistema de alta presión es?"), a: [T("Oil residue at a joint or fitting", "Residuo de aceite en una unión o conexión"), T("A loud compressor", "Un compresor ruidoso"), T("High head pressure", "Presión de alta elevada"), T("A cold condenser", "Un condensador frío")], c: 0, why: T("Refrigerant carries oil with it. Oily spots at flares, brazed joints and Schraders are the first place to check with a detector.", "El refrigerante saca aceite. Las manchas de aceite en abocinados, soldaduras y Schraders son lo primero que revisas con el detector."), wrong: ["", T("Not A loud compressor. The right call is Oil residue at a joint or fitting.", "No es Un compresor ruidoso. La correcta es Residuo de aceite en una unión o conexión."), T("Not High head pressure. The right call is Oil residue at a joint or fitting.", "No es Presión de alta elevada. La correcta es Residuo de aceite en una unión o conexión."), T("Not A cold condenser. The right call is Oil residue at a joint or fitting.", "No es Un condensador frío. La correcta es Residuo de aceite en una unión o conexión.")], tip: T("Refrigerant carries oil with it. Oily spots at flares, brazed joints and Schraders are the first place to check with a detector. (Service practice)", "El refrigerante saca aceite. Las manchas de aceite en abocinados, soldaduras y Schraders son lo primero que revisas con el detector. (Service practice)")});
  put("Before recharging after a major repair, you should:", {q: T("You're on a high-pressure split, RTU, or rack. Before recharging after a major repair, you should?", "Estás en un split, RTU o rack de alta presión. Antes de recargar después de una reparación mayor, debes?"), a: [T("Pressure test with nitrogen, then evacuate to a deep vacuum", "Probar presión con nitrógeno y luego hacer vacío profundo"), T("Charge immediately with vapor", "Cargar de inmediato con vapor"), T("Purge it with refrigerant", "Purgarlo con refrigerante"), T("Add oil only", "Solo agregar aceite")], c: 0, why: T("Nitrogen finds leaks without venting refrigerant; a micron-verified vacuum removes air and moisture.", "El nitrógeno encuentra fugas sin ventear refrigerante; un vacío verificado con micrómetro quita aire y humedad."), wrong: ["", T("Not Charge immediately with vapor. The right call is Pressure test with nitrogen, then evacuate to a deep vacuum.", "No es Cargar de inmediato con vapor. La correcta es Probar presión con nitrógeno y luego hacer vacío profundo."), T("Not Purge it with refrigerant. The right call is Pressure test with nitrogen, then evacuate to a deep vacuum.", "No es Purgarlo con refrigerante. La correcta es Probar presión con nitrógeno y luego hacer vacío profundo."), T("Not Add oil only. The right call is Pressure test with nitrogen, then evacuate to a deep vacuum.", "No es Solo agregar aceite. La correcta es Probar presión con nitrógeno y luego hacer vacío profundo.")], tip: T("Nitrogen finds leaks without venting refrigerant; a micron-verified vacuum removes air and moisture. (Service practice)", "El nitrógeno encuentra fugas sin ventear refrigerante; un vacío verificado con micrómetro quita aire y humedad. (Service practice)")});
  put("A recovery unit's discharge pressure suddenly climbs while filling a cylinder. A likely cause is:", {q: T("You're on a high-pressure split, RTU, or rack. A recovery unit's discharge pressure suddenly climbs while filling a cylinder. A likely cause is?", "Estás en un split, RTU o rack de alta presión. La presión de descarga del equipo de recuperación sube de golpe al llenar un cilindro. Causa probable?"), a: [T("The cylinder is near full or getting hot", "El cilindro está casi lleno o se está calentando"), T("The cylinder is empty", "El cilindro está vacío"), T("The hoses are too short", "Las mangueras son cortas"), T("The system is in a vacuum", "El sistema está en vacío")], c: 0, why: T("Stop and check the scale. Stay under 80% full; cooling the cylinder (ice bath) speeds recovery.", "Detente y revisa la báscula. No pases de 80%; enfriar el cilindro (baño de hielo) acelera la recuperación."), wrong: ["", T("Not The cylinder is empty. The right call is The cylinder is near full or getting hot.", "No es El cilindro está vacío. La correcta es El cilindro está casi lleno o se está calentando."), T("Not The hoses are too short. The right call is The cylinder is near full or getting hot.", "No es Las mangueras son cortas. La correcta es El cilindro está casi lleno o se está calentando."), T("Not The system is in a vacuum. The right call is The cylinder is near full or getting hot.", "No es El sistema está en vacío. La correcta es El cilindro está casi lleno o se está calentando.")], tip: T("Stop and check the scale. Stay under 80% full; cooling the cylinder (ice bath) speeds recovery. (Service practice / DOT)", "Detente y revisa la báscula. No pases de 80%; enfriar el cilindro (baño de hielo) acelera la recuperación. (Service practice / DOT)")});
  put("Why never fill a recovery cylinder past 80% by weight?", {q: T("You're on a high-pressure split, RTU, or rack. Why never fill a recovery cylinder past 80% by weight?", "Estás en un split, RTU o rack de alta presión. ¿Por qué nunca llenar un cilindro de recuperación arriba de 80% en peso?"), a: [T("Liquid expands with heat and can over-pressurize it", "El líquido se expande con el calor y puede sobrepresurizarlo"), T("The paint fades", "La pintura se despinta"), T("EPA charges by the pound", "La EPA cobra por libra"), T("Recovery slows down", "La recuperación se hace lenta")], c: 0, why: T("Leave vapor space. A liquid-full cylinder can rupture with a small temperature rise.", "Deja espacio de vapor. Un cilindro lleno de líquido puede reventar con poco aumento de temperatura."), wrong: ["", T("Not The paint fades. The right call is Liquid expands with heat and can over-pressurize it.", "No es La pintura se despinta. La correcta es El líquido se expande con el calor y puede sobrepresurizarlo."), T("Not EPA charges by the pound. The right call is Liquid expands with heat and can over-pressurize it.", "No es La EPA cobra por libra. La correcta es El líquido se expande con el calor y puede sobrepresurizarlo."), T("Not Recovery slows down. The right call is Liquid expands with heat and can over-pressurize it.", "No es La recuperación se hace lenta. La correcta es El líquido se expande con el calor y puede sobrepresurizarlo.")], tip: T("Leave vapor space. A liquid-full cylinder can rupture with a small temperature rise. (DOT / service practice)", "Deja espacio de vapor. Un cilindro lleno de líquido puede reventar con poco aumento de temperatura. (DOT / service practice)")});
  put("Why do low-pressure chillers need a purge unit?", {q: T("You're on a low-pressure chiller job. Why do low-pressure chillers need a purge unit?", "Estás en un chiller de baja presión. ¿Por qué los chillers de baja presión necesitan una unidad de purga?"), a: [T("Parts run below atmospheric pressure, so leaks pull air and moisture in", "Partes trabajan bajo presión atmosférica, así que las fugas meten aire y humedad"), T("To add oil", "Para agregar aceite"), T("To raise head pressure", "Para subir la presión de descarga"), T("To vent refrigerant on purpose", "Para ventear refrigerante a propósito")], c: 0, why: T("The evaporator side runs in a vacuum. Leaks pull air in instead of letting refrigerant out; the purge removes those non-condensables.", "El lado del evaporador trabaja en vacío. Las fugas meten aire en vez de sacar refrigerante; la purga quita esos no condensables."), wrong: ["", T("Not To add oil. The right call is Parts run below atmospheric pressure, so leaks pull air and moisture in.", "No es Para agregar aceite. La correcta es Partes trabajan bajo presión atmosférica, así que las fugas meten aire y humedad."), T("Not To raise head pressure. The right call is Parts run below atmospheric pressure, so leaks pull air and moisture in.", "No es Para subir la presión de descarga. La correcta es Partes trabajan bajo presión atmosférica, así que las fugas meten aire y humedad."), T("Not To vent refrigerant on purpose. The right call is Parts run below atmospheric pressure, so leaks pull air and moisture in.", "No es Para ventear refrigerante a propósito. La correcta es Partes trabajan bajo presión atmosférica, así que las fugas meten aire y humedad.")], tip: T("The evaporator side runs in a vacuum. Leaks pull air in instead of letting refrigerant out; the purge removes those non-condensables. (Service practice)", "El lado del evaporador trabaja en vacío. Las fugas meten aire en vez de sacar refrigerante; la purga quita esos no condensables. (Service practice)")});
  put("A rupture disc on a low-pressure chiller evaporator is commonly set at:", {q: T("You're on a low-pressure chiller job. A rupture disc on a low-pressure chiller evaporator is commonly set at?", "Estás en un chiller de baja presión. El disco de ruptura en el evaporador de un chiller de baja presión suele estar calibrado a?"), a: [T("15 psig", "15 psig"), T("150 psig", "150 psig"), T("5 psig", "5 psig"), T("300 psig", "300 psig")], c: 0, why: T("Low-pressure shells are built for low pressures, so the rupture disc is commonly rated around 15 psig.", "Las carcasas de baja presión se diseñan para presiones bajas; el disco suele ser de unos 15 psig."), wrong: ["", T("Not 150 psig. The right call is 15 psig.", "No es 150 psig. La correcta es 15 psig."), T("Not 5 psig. The right call is 15 psig.", "No es 5 psig. La correcta es 15 psig."), T("Not 300 psig. The right call is 15 psig.", "No es 300 psig. La correcta es 15 psig.")], tip: T("Low-pressure shells are built for low pressures, so the rupture disc is commonly rated around 15 psig. (Industry practice)", "Las carcasas de baja presión se diseñan para presiones bajas; el disco suele ser de unos 15 psig. (Industry practice)")});
  put("When leak testing a low-pressure system, pressure should not exceed about:", {q: T("You're on a low-pressure chiller job. When leak testing a low-pressure system, pressure should not exceed about?", "Estás en un chiller de baja presión. Al probar fugas en un sistema de baja presión, la presión no debe pasar de unos?"), a: [T("10 psig", "10 psig"), T("50 psig", "50 psig"), T("150 psig", "150 psig"), T("0 psig", "0 psig")], c: 0, why: T("Stay safely under the 15 psig rupture disc. About 10 psig is the common limit.", "Mantente debajo del disco de ruptura de 15 psig. Unos 10 psig es el límite común."), wrong: ["", T("Not 50 psig. The right call is 10 psig.", "No es 50 psig. La correcta es 10 psig."), T("Not 150 psig. The right call is 10 psig.", "No es 150 psig. La correcta es 10 psig."), T("Not 0 psig. The right call is 10 psig.", "No es 0 psig. La correcta es 10 psig.")], tip: T("Stay safely under the 15 psig rupture disc. About 10 psig is the common limit. (Service practice)", "Mantente debajo del disco de ruptura de 15 psig. Unos 10 psig es el límite común. (Service practice)")});
  put("Required evacuation level for a low-pressure appliance (recovery equipment made after Nov. 15, 1993):", {q: T("You're on a low-pressure chiller job. Required evacuation level for a low-pressure appliance (recovery equipment made after Nov. 15, 1993)?", "Estás en un chiller de baja presión. Nivel de evacuación para un aparato de baja presión (equipo de recuperación posterior al 15 nov. 1993)?"), a: [T("25 mm Hg absolute", "25 mm Hg absolutos"), T("0 in. Hg", "0 in Hg"), T("10 in. Hg", "10 in Hg"), T("4 in. Hg", "4 in Hg")], c: 0, why: T("Low-pressure appliances must reach 25 mm Hg absolute before opening (Table 1), with either old or new equipment.", "Los aparatos de baja presión deben llegar a 25 mm Hg absolutos antes de abrirse (Tabla 1), con equipo viejo o nuevo."), wrong: ["", T("Not 0 in. Hg. The right call is 25 mm Hg absolute.", "No es 0 in Hg. La correcta es 25 mm Hg absolutos."), T("Not 10 in. Hg. The right call is 25 mm Hg absolute.", "No es 10 in Hg. La correcta es 25 mm Hg absolutos."), T("Not 4 in. Hg. The right call is 25 mm Hg absolute.", "No es 4 in Hg. La correcta es 25 mm Hg absolutos.")], tip: T("Low-pressure appliances must reach 25 mm Hg absolute before opening (Table 1), with either old or new equipment. (40 CFR 82.156(a), Table 1)", "Los aparatos de baja presión deben llegar a 25 mm Hg absolutos antes de abrirse (Tabla 1), con equipo viejo o nuevo. (40 CFR 82.156(a), Table 1)")});
  put("While recovering refrigerant from a chiller, water should be circulated through the tubes to:", {q: T("You're on a low-pressure chiller job. While recovering refrigerant from a chiller, water should be circulated through the tubes to?", "Estás en un chiller de baja presión. Al recuperar refrigerante de un chiller, se debe circular agua por los tubos para?"), a: [T("Prevent tubes from freezing", "Evitar que los tubos se congelen"), T("Speed up the purge", "Acelerar la purga"), T("Add heat to the recovery unit", "Darle calor al equipo de recuperación"), T("Flush the oil", "Lavar el aceite")], c: 0, why: T("As pressure drops, refrigerant temperature drops too. Moving water keeps the tubes from freezing and cracking.", "Al bajar la presión baja la temperatura del refrigerante. El agua en movimiento evita que los tubos se congelen y revienten."), wrong: ["", T("Not Speed up the purge. The right call is Prevent tubes from freezing.", "No es Acelerar la purga. La correcta es Evitar que los tubos se congelen."), T("Not Add heat to the recovery unit. The right call is Prevent tubes from freezing.", "No es Darle calor al equipo de recuperación. La correcta es Evitar que los tubos se congelen."), T("Not Flush the oil. The right call is Prevent tubes from freezing.", "No es Lavar el aceite. La correcta es Evitar que los tubos se congelen.")], tip: T("As pressure drops, refrigerant temperature drops too. Moving water keeps the tubes from freezing and cracking. (Service practice)", "Al bajar la presión baja la temperatura del refrigerante. El agua en movimiento evita que los tubos se congelen y revienten. (Service practice)")});
  put("A 'low-pressure appliance' uses a refrigerant whose liquid saturation pressure at 104°F is:", {q: T("You're on a low-pressure chiller job. A 'low-pressure appliance' uses a refrigerant whose liquid saturation pressure at 104°F is?", "Estás en un chiller de baja presión. Un 'aparato de baja presión' usa refrigerante con presión de saturación líquida a 104°F?"), a: [T("Below 45 psia", "Menor a 45 psia"), T("45–170 psia", "45–170 psia"), T("170–355 psia", "170–355 psia"), T("Above 355 psia", "Mayor a 355 psia")], c: 0, why: T("Examples include R-11, R-123, R-113 and R-245fa, mostly centrifugal chillers.", "Ejemplos: R-11, R-123, R-113 y R-245fa, sobre todo chillers centrífugos."), wrong: ["", T("Not 45–170 psia. The right call is Below 45 psia.", "No es 45–170 psia. La correcta es Menor a 45 psia."), T("Not 170–355 psia. The right call is Below 45 psia.", "No es 170–355 psia. La correcta es Menor a 45 psia."), T("Not Above 355 psia. The right call is Below 45 psia.", "No es Mayor a 355 psia. La correcta es Menor a 45 psia.")], tip: T("Examples include R-11, R-123, R-113 and R-245fa, mostly centrifugal chillers. (40 CFR 82.152 (definitions))", "Ejemplos: R-11, R-123, R-113 y R-245fa, sobre todo chillers centrífugos. (40 CFR 82.152 (definitions))")});
  put("Which refrigerant is used in low-pressure chillers?", {q: T("You're on a low-pressure chiller job. Which refrigerant is used in low-pressure chillers?", "Estás en un chiller de baja presión. ¿Qué refrigerante se usa en chillers de baja presión?"), a: [T("R-123", "R-123"), T("R-410A", "R-410A"), T("R-134a", "R-134a"), T("R-22", "R-22")], c: 0, why: T("R-123 (and older R-11) chillers run with the evaporator in a vacuum.", "Los chillers de R-123 (y los viejos de R-11) trabajan con el evaporador en vacío."), wrong: ["", T("Not R-410A. The right call is R-123.", "No es R-410A. La correcta es R-123."), T("Not R-134a. The right call is R-123.", "No es R-134a. La correcta es R-123."), T("Not R-22. The right call is R-123.", "No es R-22. La correcta es R-123.")], tip: T("R-123 (and older R-11) chillers run with the evaporator in a vacuum. (40 CFR 82.152 (definitions))", "Los chillers de R-123 (y los viejos de R-11) trabajan con el evaporador en vacío. (40 CFR 82.152 (definitions))")});
  put("Who must service and dispose of low-pressure appliances?", {q: T("You're on a low-pressure chiller job. Who must service and dispose of low-pressure appliances?", "Estás en un chiller de baja presión. ¿Quién debe dar servicio y desechar aparatos de baja presión?"), a: [T("Type III or Universal technicians", "Técnicos Tipo III o Universal"), T("Type I technicians", "Técnicos Tipo I"), T("Type II technicians", "Técnicos Tipo II"), T("Anyone", "Cualquiera")], c: 0, why: T("Type III covers low-pressure appliances.", "El Tipo III cubre aparatos de baja presión."), wrong: ["", T("Not Type I technicians. The right call is Type III or Universal technicians.", "No es Técnicos Tipo I. La correcta es Técnicos Tipo III o Universal."), T("Not Type II technicians. The right call is Type III or Universal technicians.", "No es Técnicos Tipo II. La correcta es Técnicos Tipo III o Universal."), T("Not Anyone. The right call is Type III or Universal technicians.", "No es Cualquiera. La correcta es Técnicos Tipo III o Universal.")], tip: T("Type III covers low-pressure appliances. (40 CFR 82.161(a)(1)(iii))", "El Tipo III cubre aparatos de baja presión. (40 CFR 82.161(a)(1)(iii))")});
  put("For a NON-major repair on a low-pressure appliance (not evacuated to atmosphere afterward), before opening you must:", {q: T("You're on a low-pressure chiller job. For a NON-major repair on a low-pressure appliance (not evacuated to atmosphere afterward), before opening you must?", "Estás en un chiller de baja presión. Para una reparación NO mayor en un equipo de baja presión (que no se evacuará a la atmósfera después), antes de abrir debes?"), a: [T("Pressurize it to no higher than 0 psig", "Presurizarlo a no más de 0 psig"), T("Pull it to 25 mm Hg absolute", "Llevarlo a 25 mm Hg absolutos"), T("Raise it to 15 psig", "Subirlo a 15 psig"), T("Open it in a vacuum", "Abrirlo en vacío")], c: 0, why: T("Low-pressure systems sit below atmosphere. You bring them UP to about 0 psig so air doesn't rush in when opened.", "Los sistemas de baja trabajan bajo la atmósfera. Se SUBEN a unos 0 psig para que no entre aire al abrir."), wrong: ["", T("Not Pull it to 25 mm Hg absolute. The right call is Pressurize it to no higher than 0 psig.", "No es Llevarlo a 25 mm Hg absolutos. La correcta es Presurizarlo a no más de 0 psig."), T("Not Raise it to 15 psig. The right call is Pressurize it to no higher than 0 psig.", "No es Subirlo a 15 psig. La correcta es Presurizarlo a no más de 0 psig."), T("Not Open it in a vacuum. The right call is Pressurize it to no higher than 0 psig.", "No es Abrirlo en vacío. La correcta es Presurizarlo a no más de 0 psig.")], tip: T("Low-pressure systems sit below atmosphere. You bring them UP to about 0 psig so air doesn't rush in when opened. (40 CFR 82.156(a)(1)(ii))", "Los sistemas de baja trabajan bajo la atmósfera. Se SUBEN a unos 0 psig para que no entre aire al abrir. (40 CFR 82.156(a)(1)(ii))")});
  put("Raising the pressure of an R-123 chiller (boils below 85°F) for a non-major repair, you must NOT:", {q: T("You're on a low-pressure chiller job. Raising the pressure of an R-123 chiller (boils below 85°F) for a non-major repair, you must NOT?", "Estás en un chiller de baja presión. Al subir la presión de un chiller de R-123 (hierve bajo 85°F) para una reparación no mayor, NO debes?"), a: [T("Use nitrogen or other methods that need purging later", "Usar nitrógeno u otros métodos que requieran purga después"), T("Use controlled hot water", "Usar agua caliente controlada"), T("Use heater blankets", "Usar mantas térmicas"), T("Cover openings", "Tapar las aberturas")], c: 0, why: T("For refrigerants boiling at or below 85°F, the rule bans methods like nitrogen that require later purging. Use heat.", "Para refrigerantes que hierven a 85°F o menos, la regla prohíbe métodos como nitrógeno que luego requieren purga. Usa calor."), wrong: ["", T("Not Use controlled hot water. The right call is Use nitrogen or other methods that need purging later.", "No es Usar agua caliente controlada. La correcta es Usar nitrógeno u otros métodos que requieran purga después."), T("Not Use heater blankets. The right call is Use nitrogen or other methods that need purging later.", "No es Usar mantas térmicas. La correcta es Usar nitrógeno u otros métodos que requieran purga después."), T("Not Cover openings. The right call is Use nitrogen or other methods that need purging later.", "No es Tapar las aberturas. La correcta es Usar nitrógeno u otros métodos que requieran purga después.")], tip: T("For refrigerants boiling at or below 85°F, the rule bans methods like nitrogen that require later purging. Use heat. (40 CFR 82.156(a)(1)(ii))", "Para refrigerantes que hierven a 85°F o menos, la regla prohíbe métodos como nitrógeno que luego requieren purga. Usa calor. (40 CFR 82.156(a)(1)(ii))")});
  put("For low-pressure refrigerants boiling ABOVE 85°F (like R-113), to reach atmospheric pressure you must:", {q: T("You're on a low-pressure chiller job. For low-pressure refrigerants boiling ABOVE 85°F (like R-113), to reach atmospheric pressure you must?", "Estás en un chiller de baja presión. Para refrigerantes de baja que hierven ARRIBA de 85°F (como R-113), para llegar a presión atmosférica debes?"), a: [T("Use heat as much as possible; nitrogen may finish the rise", "Usar calor lo más posible; el nitrógeno puede terminar"), T("Use only nitrogen", "Usar solo nitrógeno"), T("Use compressed air", "Usar aire comprimido"), T("Do nothing", "No hacer nada")], c: 0, why: T("Heat first; nitrogen is only allowed from the heat-attained level up to atmospheric pressure.", "Primero calor; el nitrógeno solo se permite del nivel alcanzado con calor a presión atmosférica."), wrong: ["", T("Not Use only nitrogen. The right call is Use heat as much as possible; nitrogen may finish the rise.", "No es Usar solo nitrógeno. La correcta es Usar calor lo más posible; el nitrógeno puede terminar."), T("Not Use compressed air. The right call is Use heat as much as possible; nitrogen may finish the rise.", "No es Usar aire comprimido. La correcta es Usar calor lo más posible; el nitrógeno puede terminar."), T("Not Do nothing. The right call is Use heat as much as possible; nitrogen may finish the rise.", "No es No hacer nada. La correcta es Usar calor lo más posible; el nitrógeno puede terminar.")], tip: T("Heat first; nitrogen is only allowed from the heat-attained level up to atmospheric pressure. (40 CFR 82.156(a)(1)(ii))", "Primero calor; el nitrógeno solo se permite del nivel alcanzado con calor a presión atmosférica. (40 CFR 82.156(a)(1)(ii))")});
  put("A chiller with 200 lb of R-123 is opened for major repair using 2010 recovery equipment. Evacuate to:", {q: T("You're on a low-pressure chiller job. A chiller with 200 lb of R-123 is opened for major repair using 2010 recovery equipment. Evacuate to?", "Estás en un chiller de baja presión. Un chiller con 200 lb de R-123 se abre para reparación mayor con equipo de recuperación de 2010. Evacúa a?"), a: [T("25 mm Hg absolute", "25 mm Hg absolutos"), T("0 in. Hg", "0 in Hg"), T("10 in. Hg", "10 in Hg"), T("15 in. Hg", "15 in Hg")], c: 0, why: T("Low-pressure appliances: 25 mm Hg absolute regardless of charge size.", "Baja presión: 25 mm Hg absolutos sin importar el tamaño de la carga."), wrong: ["", T("Not 0 in. Hg. The right call is 25 mm Hg absolute.", "No es 0 in Hg. La correcta es 25 mm Hg absolutos."), T("Not 10 in. Hg. The right call is 25 mm Hg absolute.", "No es 10 in Hg. La correcta es 25 mm Hg absolutos."), T("Not 15 in. Hg. The right call is 25 mm Hg absolute.", "No es 15 in Hg. La correcta es 25 mm Hg absolutos.")], tip: T("Low-pressure appliances: 25 mm Hg absolute regardless of charge size. (40 CFR 82.156(a), Table 1)", "Baja presión: 25 mm Hg absolutos sin importar el tamaño de la carga. (40 CFR 82.156(a), Table 1)")});
  put("25 mm Hg absolute is roughly how many inches of mercury vacuum?", {q: T("You're on a low-pressure chiller job. 25 mm Hg absolute is roughly how many inches of mercury vacuum?", "Estás en un chiller de baja presión. 25 mm Hg absolutos son aproximadamente cuántas pulgadas de mercurio de vacío?"), a: [T("About 29 in. Hg vacuum", "Unas 29 in Hg de vacío"), T("About 10 in. Hg", "Unas 10 in Hg"), T("About 15 in. Hg", "Unas 15 in Hg"), T("0 in. Hg", "0 in Hg")], c: 0, why: T("Atmosphere is ~760 mm Hg (29.9 in). 25 mm Hg absolute leaves about 1 inch, so roughly 28.9 in. Hg vacuum.", "La atmósfera son ~760 mm Hg (29.9 in). 25 mm Hg absolutos dejan cerca de 1 pulgada, o sea ~28.9 in Hg de vacío."), wrong: ["", T("Not About 10 in. Hg. The right call is About 29 in. Hg vacuum.", "No es Unas 10 in Hg. La correcta es Unas 29 in Hg de vacío."), T("Not About 15 in. Hg. The right call is About 29 in. Hg vacuum.", "No es Unas 15 in Hg. La correcta es Unas 29 in Hg de vacío."), T("Not 0 in. Hg. The right call is About 29 in. Hg vacuum.", "No es 0 in Hg. La correcta es Unas 29 in Hg de vacío.")], tip: T("Atmosphere is ~760 mm Hg (29.9 in). 25 mm Hg absolute leaves about 1 inch, so roughly 28.9 in. Hg vacuum. (Unit math · 40 CFR 82.156 Table 1)", "La atmósfera son ~760 mm Hg (29.9 in). 25 mm Hg absolutos dejan cerca de 1 pulgada, o sea ~28.9 in Hg de vacío. (Unit math · 40 CFR 82.156 Table 1)")});
  put("Recovering from a low-pressure chiller: remove the liquid first, then:", {q: T("You're on a low-pressure chiller job. Recovering from a low-pressure chiller: remove the liquid first, then?", "Estás en un chiller de baja presión. Al recuperar de un chiller de baja: saca primero el líquido y luego?"), a: [T("Recover the remaining vapor to the required level", "Recupera el vapor restante hasta el nivel requerido"), T("Vent the vapor", "Ventea el vapor"), T("Add nitrogen and open it", "Mete nitrógeno y ábrelo"), T("Stop; vapor doesn't count", "Detente; el vapor no cuenta")], c: 0, why: T("A big shell holds a lot of refrigerant as vapor. You still have to reach 25 mm Hg absolute.", "Una carcasa grande guarda mucho refrigerante como vapor. Igual debes llegar a 25 mm Hg absolutos."), wrong: ["", T("Not Vent the vapor. The right call is Recover the remaining vapor to the required level.", "No es Ventea el vapor. La correcta es Recupera el vapor restante hasta el nivel requerido."), T("Not Add nitrogen and open it. The right call is Recover the remaining vapor to the required level.", "No es Mete nitrógeno y ábrelo. La correcta es Recupera el vapor restante hasta el nivel requerido."), T("Not Stop; vapor doesn't count. The right call is Recover the remaining vapor to the required level.", "No es Detente; el vapor no cuenta. La correcta es Recupera el vapor restante hasta el nivel requerido.")], tip: T("A big shell holds a lot of refrigerant as vapor. You still have to reach 25 mm Hg absolute. (Service practice · 40 CFR 82.156)", "Una carcasa grande guarda mucho refrigerante como vapor. Igual debes llegar a 25 mm Hg absolutos. (Service practice · 40 CFR 82.156)")});
  put("High-efficiency purge units matter because:", {q: T("You're on a low-pressure chiller job. High-efficiency purge units matter because?", "Estás en un chiller de baja presión. Las purgas de alta eficiencia importan porque?"), a: [T("They remove air while releasing very little refrigerant", "Sacan el aire liberando muy poco refrigerante"), T("They add refrigerant automatically", "Agregan refrigerante solas"), T("They replace the rupture disc", "Reemplazan el disco de ruptura"), T("They cool the motor", "Enfrían el motor")], c: 0, why: T("Old purges vented a lot of refrigerant with the air. Purged refrigerant destroyed at ≥98% efficiency isn't counted toward the leak rate.", "Las purgas viejas tiraban mucho refrigerante con el aire. Lo purgado que se destruye con ≥98% de eficiencia no cuenta en la tasa de fuga."), wrong: ["", T("Not They add refrigerant automatically. The right call is They remove air while releasing very little refrigerant.", "No es Agregan refrigerante solas. La correcta es Sacan el aire liberando muy poco refrigerante."), T("Not They replace the rupture disc. The right call is They remove air while releasing very little refrigerant.", "No es Reemplazan el disco de ruptura. La correcta es Sacan el aire liberando muy poco refrigerante."), T("Not They cool the motor. The right call is They remove air while releasing very little refrigerant.", "No es Enfrían el motor. La correcta es Sacan el aire liberando muy poco refrigerante.")], tip: T("Old purges vented a lot of refrigerant with the air. Purged refrigerant destroyed at ≥98% efficiency isn't counted toward the leak rate. (40 CFR 82.157(k))", "Las purgas viejas tiraban mucho refrigerante con el aire. Lo purgado que se destruye con ≥98% de eficiencia no cuenta en la tasa de fuga. (40 CFR 82.157(k))")});
